{

"kind": "propose",
"summary": "Increase probe timeouts to match application response times",
"hypotheses": [
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "Readiness and liveness probes timeout before the application can respond",
        "supporting": ["probe_timeouts", "ev-rollout_history", "ev-target_events", "ev-container_logs_tail"],
        "contradicting": [],
        "missing": [],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "Need to verify if probe timeouts are the root cause",
        "supporting": [],
        "contradicting": ["probe_timeouts", "crashed_on_its_own"],
        "missing": [],
        "status": "refuted"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "search-api",
        "uid": "uid-deployment-search-api"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        },
        "readiness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Reduce probe timeouts to allow the application sufficient time to respond before timing out",
    "rationale": "The application's logs (ev-container_logs_tail) show it responds to /ready and /healthz endpoints with 1.2s+ latency, but probes timeout after 1s (ev-rollout_history). Increasing timeouts to 5s accommodates this latency while maintaining probe effectiveness. This directly addresses the probe_timeout_too_short hypothesis, as the application is functional but takes longer than the probe's allowed time to respond.",
    "cited_evidence_ids": ["probe_timeouts", "ev-rollout_history", "ev-target_events", "ev-container_logs_tail"],
    "cited_predicates": ["probe_timeouts", "crashed_on_its_own"]
}
}
